<?php $title='فروشگاه'; require __DIR__.'/partials/header.php'; $q=trim($_GET['q']??'');$cat=(int)($_GET['category']??0);$sort=$_GET['sort']??'new';$where=['p.active=1'];$params=[];if($q!==''){$where[]='(p.name LIKE ? OR p.description LIKE ? OR p.sku LIKE ?)';$params=["%$q%","%$q%","%$q%"]; }if($cat){$where[]='p.category_id=?';$params[]=$cat;} $order=$sort==='price_asc'?'p.price ASC':($sort==='price_desc'?'p.price DESC':($sort==='popular'?'p.sales DESC':'p.id DESC'));$cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();$sql='SELECT p.* FROM products p WHERE '.implode(' AND ',$where).' ORDER BY '.$order; $s=$pdo->prepare($sql);$s->execute($params);$products=$s->fetchAll(); ?>
<h1>فروشگاه</h1><form class="toolbar"><input class="grow" name="q" value="<?=e($q)?>" placeholder="جستجوی نام، توضیحات یا SKU"><select name="category" data-auto-submit><option value="0">همه دسته‌ها</option><?php foreach($cats as $c): ?><option value="<?=$c['id']?>" <?=$cat==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach; ?></select><select name="sort" data-auto-submit><option value="new" <?=$sort==='new'?'selected':''?>>جدیدترین</option><option value="popular" <?=$sort==='popular'?'selected':''?>>پرفروش‌ترین</option><option value="price_asc" <?=$sort==='price_asc'?'selected':''?>>ارزان‌ترین</option><option value="price_desc" <?=$sort==='price_desc'?'selected':''?>>گران‌ترین</option></select><button class="btn">جستجو</button></form><div class="grid"><?php foreach($products as $p): ?><article class="card"><img class="product-img" src="<?=e($p['image']?:'https://placehold.co/600x600?text=SHOPX')?>"><div class="card-body"><div class="rating">★★★★★</div><h3><a href="<?=url('product.php?id='.$p['id'])?>"><?=e($p['name'])?></a></h3><div class="muted">موجودی: <?=e($p['stock'])?></div><div class="price" style="margin-top:8px"><?=money($p['price'])?></div><div style="margin-top:10px"><a class="btn small" href="<?=url('cart.php?add='.$p['id'])?>">افزودن</a></div></div></article><?php endforeach; ?></div><?php if(!$products): ?><div class="panel empty">محصولی پیدا نشد.</div><?php endif; ?>
<?php require __DIR__.'/partials/footer.php'; ?>
